import React, { useState } from 'react';
import { BookOpen, CheckCircle, Volume2, Sparkles, RefreshCw } from 'lucide-react';
import { checkGrammar, textToSpeech } from '../services/api';

const GrammarTool = ({ languages, selectedLang, username }) => {
  const [targetLang, setTargetLang] = useState(selectedLang || 'es');
  const [inputText, setInputText] = useState('');
  const [analysisResult, setAnalysisResult] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);

  const handleAnalyze = async () => {
    if (!inputText.trim()) return;
    setIsLoading(true);
    try {
      const res = await checkGrammar(inputText, targetLang, username);
      setAnalysisResult(res);
    } catch (e) {
      console.error("Grammar check error:", e);
      setAnalysisResult({
        analysis_and_correction: "Grammar analysis error. Please ensure backend is connected.",
        corrected_text: inputText
      });
    } finally {
      setIsLoading(false);
    }
  };

  const speakText = (textToSpeak) => {
    if (!textToSpeak) return;
    if (isPlayingAudio) {
      window.speechSynthesis?.cancel();
      setIsPlayingAudio(false);
      return;
    }

    setIsPlayingAudio(true);

    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(textToSpeak);
      utterance.lang = targetLang;
      utterance.rate = 0.9;
      utterance.onend = () => setIsPlayingAudio(false);
      utterance.onerror = () => {
        fallbackBackendTTS(textToSpeak);
      };
      window.speechSynthesis.speak(utterance);
    } else {
      fallbackBackendTTS(textToSpeak);
    }
  };

  const fallbackBackendTTS = async (textToSpeak) => {
    try {
      const audioUrl = await textToSpeech(textToSpeak, targetLang);
      const audio = new Audio(audioUrl);
      audio.onended = () => setIsPlayingAudio(false);
      audio.onerror = () => setIsPlayingAudio(false);
      await audio.play();
    } catch (e) {
      console.error("Backend TTS Error:", e);
      setIsPlayingAudio(false);
    }
  };

  const sampleSentences = [
    "Yo ir a la tienda ayer.",
    "She do not like cold weather.",
    "Je suis aller au cinéma demain."
  ];

  const langMeta = languages[targetLang] || { name: targetLang, flag: '🌐' };

  return (
    <div className="glass-panel" style={{ flex: 1, display: 'flex', flexDirection: 'column', padding: '24px', gap: '20px', overflowY: 'auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderBottom: '1px solid rgba(255, 255, 255, 0.1)', paddingBottom: '16px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{ background: 'linear-gradient(135deg, #3b82f6, #8b5cf6)', padding: '10px', borderRadius: '12px' }}>
            <BookOpen size={20} color="#fff" />
          </div>
          <div>
            <h2 style={{ fontSize: '18px', fontWeight: 700, color: '#fff' }}>Grammar, Punctuation & Phonetic Sounds Studio</h2>
            <p style={{ fontSize: '12px', color: '#9ca3af' }}>Analyze sentence structure, punctuation marks, spelling, and listen to authentic sound pronunciation</p>
          </div>
        </div>

        {/* Target Language Selector */}
        <select 
          value={targetLang}
          onChange={(e) => setTargetLang(e.target.value)}
          style={{
            background: 'rgba(30, 41, 59, 0.9)',
            border: '1px solid rgba(255, 255, 255, 0.15)',
            borderRadius: '10px',
            padding: '8px 14px',
            color: '#fff',
            fontSize: '13px',
            outline: 'none',
            cursor: 'pointer'
          }}
        >
          {Object.entries(languages || {}).map(([code, meta]) => (
            <option key={code} value={code}>
              {meta.flag} {meta.name} ({meta.native})
            </option>
          ))}
        </select>
      </div>

      {/* Input Area */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <label style={{ fontSize: '13px', color: '#9ca3af', fontWeight: 500 }}>
          Enter a sentence in {langMeta.name} to evaluate:
        </label>
        <textarea 
          placeholder={`Type a sentence in ${langMeta.name} (checks grammar, punctuation marks, spelling, and sound pronunciation)...`}
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          style={{
            minHeight: '120px',
            background: 'rgba(15, 23, 42, 0.8)',
            border: '1px solid rgba(255, 255, 255, 0.15)',
            borderRadius: '12px',
            padding: '14px',
            color: '#fff',
            fontSize: '14px',
            lineHeight: '1.6',
            resize: 'none',
            outline: 'none'
          }}
        />

        <button 
          onClick={handleAnalyze} 
          disabled={isLoading || !inputText.trim()}
          className="glow-btn"
          style={{ padding: '12px' }}
        >
          {isLoading ? <RefreshCw size={16} className="animate-spin" /> : <Sparkles size={16} />}
          <span>{isLoading ? 'Analyzing Grammar, Punctuation & Sounds...' : 'Analyze Grammar, Punctuation & Sounds'}</span>
        </button>
      </div>

      {/* Analysis Output Result Card */}
      {analysisResult && (
        <div 
          style={{
            background: 'linear-gradient(135deg, rgba(30, 41, 59, 0.9), rgba(15, 23, 42, 0.9))',
            border: '1px solid rgba(139, 92, 246, 0.3)',
            borderRadius: '14px',
            padding: '20px',
            display: 'flex',
            flexDirection: 'column',
            gap: '14px'
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#c084fc', fontSize: '14px', fontWeight: 600 }}>
              <CheckCircle size={18} color="#10b981" />
              <span>AI Tutoring Breakdown:</span>
            </div>

            {analysisResult.corrected_text && (
              <button
                onClick={() => speakText(analysisResult.corrected_text)}
                style={{
                  background: isPlayingAudio ? 'rgba(239, 68, 68, 0.2)' : 'rgba(59, 130, 246, 0.2)',
                  border: isPlayingAudio ? '1px solid rgba(239, 68, 68, 0.4)' : '1px solid rgba(59, 130, 246, 0.4)',
                  color: isPlayingAudio ? '#fca5a5' : '#60a5fa',
                  padding: '6px 12px',
                  borderRadius: '8px',
                  fontSize: '12px',
                  fontWeight: 600,
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px'
                }}
              >
                <Volume2 size={16} />
                <span>{isPlayingAudio ? 'Stop Sound' : 'Listen Corrected Sound'}</span>
              </button>
            )}
          </div>

          <div style={{ color: '#fff', fontSize: '14px', lineHeight: '1.7', whiteSpace: 'pre-wrap', userSelect: 'text' }}>
            {analysisResult.analysis_and_correction}
          </div>
        </div>
      )}

      {/* Preset Practice Sentences */}
      <div style={{ borderTop: '1px solid rgba(255, 255, 255, 0.1)', paddingTop: '14px' }}>
        <div style={{ fontSize: '12px', color: '#9ca3af', marginBottom: '8px' }}>Test sample practice sentences with intentional errors:</div>
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          {sampleSentences.map((sentence, i) => (
            <button 
              key={i}
              onClick={() => { setInputText(sentence); }}
              className="icon-action-btn"
              style={{ fontSize: '12px' }}
            >
              "{sentence}"
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default GrammarTool;
